sys_script_include.script:
var AssetInventoryUtils = Class.create();
AssetInventoryUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    /**
     * Checks if a refurbished asset is in stock for the requested device type.
     * Can be called via GlideAjax from the portal or directly from server scripts.
     */
    checkStockAvailability: function(deviceType) {
        if (!deviceType) {
            deviceType = this.getParameter('sysparm_device_type');
        }

        var result = {
            available: false,
            assetSysId: '',
            assetTag: ''
        };

        if (!deviceType) {
            return JSON.stringify(result);
        }

        var assetGr = new GlideRecord('x_2240997_smarti_0_it_asset');
        assetGr.addQuery('device_type', deviceType);
        assetGr.addQuery('status', 'in_stock');
        assetGr.addQuery('condition', 'refurbished');
        assetGr.setLimit(1);
        assetGr.query();

        if (assetGr.next()) {
            result.available = true;
            result.assetSysId = assetGr.getUniqueValue();
            result.assetTag = assetGr.getValue('asset_tag');
        }

        return JSON.stringify(result);
    },

    /**
     * Assigns the identified refurbished asset to the requester.
     * Called during zero-touch fulfillment in Flow Designer.
     */
    assignRefurbishedAsset: function(assetSysId, userSysId, requestSysId) {
        if (!assetSysId || !userSysId) {
            return false;
        }

        var assetGr = new GlideRecord('x_2240997_smarti_0_it_asset');
        if (assetGr.get(assetSysId)) {
            assetGr.setValue('status', 'assigned');
            assetGr.setValue('assigned_to', userSysId);
            assetGr.update();

            // Link asset back to Hardware Request record
            var reqGr = new GlideRecord('x_2240997_smarti_0_hardware_request');
            if (reqGr.get(requestSysId)) {
                reqGr.setValue('linked_asset', assetSysId);
                reqGr.setValue('fulfillment_mode', 'refurbished_allocation');
                reqGr.setValue('state', 3); // 3 = Closed Complete
                reqGr.update();
            }
            return true;
        }
        return false;
    },

    type: 'AssetInventoryUtils'
});
